create or replace function public.schedule_relation_unary_violates_v1(p_type text,p_params jsonb,p_day smallint,p_start smallint,p_end smallint) returns boolean language plpgsql immutable set search_path=public as $$ declare t text:=upper(coalesce(p_type,''));v int;days int[];periods int[];day_ok boolean;begin if t='STARTS_DAY' then v:=coalesce(nullif(p_params->>'first_period','')::int,1);return p_start<>v;elsif t='ENDS_DAY' then if nullif(p_params->>'last_period','') is null then return false;end if;return p_end<>(p_params->>'last_period')::int;end if;select coalesce(array_agg(x::int),'{}') into days from jsonb_array_elements_text(coalesce(p_params->'days','[]'::jsonb))x;select coalesce(array_agg(x::int),'{}') into periods from jsonb_array_elements_text(coalesce(p_params->'periods','[]'::jsonb))x;if cardinality(days)=0 and cardinality(periods)=0 then return false;end if;day_ok:=cardinality(days)=0 or p_day=any(days);if t='PREFERRED_START' then return not(day_ok and(cardinality(periods)=0 or p_start=any(periods)));elsif t='PREFERRED_SLOT' then return not(day_ok and(cardinality(periods)=0 or not exists(select 1 from generate_series(p_start,p_end)q where not q=any(periods))));elsif t='FORBIDDEN_SLOT' then return day_ok and(cardinality(periods)=0 or exists(select 1 from generate_series(p_start,p_end)q where q=any(periods)));end if;return false;end $$;
create or replace function public.schedule_relation_pair_violates_v1(p_type text,p_params jsonb,l_day smallint,l_start smallint,l_end smallint,l_room uuid,r_day smallint,r_start smallint,r_end smallint,r_room uuid) returns boolean language plpgsql immutable set search_path=public as $$ declare t text:=upper(coalesce(p_type,''));n int:=coalesce(nullif(coalesce(p_params->>'periods',p_params->>'gap',p_params->>'days',p_params->>'value'),'')::int,0);g int;ov boolean;adj boolean;begin ov:=l_day=r_day and l_start<=r_end and r_start<=l_end;adj:=l_day=r_day and(r_start=l_end+1 or l_start=r_end+1);if t='SAME_TIME' then return l_day<>r_day or l_start<>r_start;elsif t='DIFFERENT_TIME' then return l_day=r_day and l_start=r_start;elsif t='SAME_START' then return l_start<>r_start;elsif t='SAME_DAY' then return l_day<>r_day;elsif t='DIFFERENT_DAY' then return l_day=r_day;elsif t='SAME_ROOM' then return l_room is not null and r_room is not null and l_room<>r_room;elsif t='DIFFERENT_ROOM' then return l_room is not null and r_room is not null and l_room=r_room;elsif t='ORDERED' then return not(l_day<r_day or(l_day=r_day and l_end<r_start));elsif t='CONSECUTIVE' then return l_day<>r_day or r_start<>l_end+1;elsif t='ADJACENT' then return not adj;elsif t='SAME_ROOM_IF_CONSECUTIVE' then return adj and l_room is not null and r_room is not null and l_room<>r_room;elsif t='OVERLAP' then return not ov;elsif t='NOT_OVERLAP' then return ov;elsif t='MIN_DAYS' then return abs(l_day-r_day)<n;elsif t='MAX_DAYS' then return abs(l_day-r_day)>n;elsif t in('MIN_GAP','MAX_GAP') then if l_day<>r_day then return t='MAX_GAP';end if;if l_end<r_start then g:=r_start-l_end-1;elsif r_end<l_start then g:=l_start-r_end-1;else g:=-1;end if;return case when t='MIN_GAP' then g<n else g>n end;end if;return false;end $$;
create or replace function public.validate_schedule_planning_relation_definition_v1() returns trigger language plpgsql set search_path=public as $$ declare t text:=upper(btrim(new.relation_type));begin if t<>all(array['SAME_TIME','DIFFERENT_TIME','SAME_START','SAME_DAY','DIFFERENT_DAY','SAME_ROOM','DIFFERENT_ROOM','ORDERED','CONSECUTIVE','ADJACENT','OVERLAP','NOT_OVERLAP','MIN_GAP','MAX_GAP','MIN_DAYS','MAX_DAYS','SAME_ROOM_IF_CONSECUTIVE','STARTS_DAY','ENDS_DAY','PREFERRED_START','PREFERRED_SLOT','FORBIDDEN_SLOT','GROUPED','MAX_SIMULTANEOUS','MAX_OCCUPIED_SLOTS','MAX_DIFFERENT_ROOMS']) then raise exception 'UNSUPPORTED_PLANNING_RELATION_TYPE: %',t;end if;new.relation_type:=t;new.left_selector:=coalesce(new.left_selector,'{}'::jsonb);new.right_selector:=coalesce(new.right_selector,'{}'::jsonb);new.parameters:=coalesce(new.parameters,'{}'::jsonb);if t in('STARTS_DAY','ENDS_DAY','PREFERRED_START','PREFERRED_SLOT','FORBIDDEN_SLOT','GROUPED','MAX_SIMULTANEOUS','MAX_OCCUPIED_SLOTS','MAX_DIFFERENT_ROOMS') then new.right_selector:='{}'::jsonb;end if;return new;end $$;
create or replace function public.get_schedule_relation_selected_activities_v1(p_relation_id uuid,p_scenario_id uuid default null) returns table(activity_key text,assignment_id uuid,course_id uuid,teacher_id uuid,class_id uuid,weekday smallint,start_p smallint,end_p smallint,classroom_id uuid) language plpgsql stable security definer set search_path=public as $$ declare sel jsonb;begin if p_scenario_id is not null then perform public.assert_schedule_scenario_tenant_phase3_v1(p_scenario_id);end if;select left_selector into sel from public.schedule_planning_relations where id=p_relation_id and active and tenant_row_allowed(institution_code);if sel is null then return;end if;return query with raw as(select ts.id,ts.block_key,ts.teacher_assignment_id assignment_id,ts.course_id,ts.teacher_id,ts.class_id,ts.weekday,ts.period,ts.classroom_id from public.teacher_schedule ts where p_scenario_id is null and ts.active and ts.institution_code=public.current_tenant_code() union all select sr.id,sr.block_key,sr.teacher_assignment_id,sr.course_id,sr.teacher_id,sr.class_id,sr.weekday,sr.period,sr.classroom_id from public.schedule_scenario_rows sr where p_scenario_id is not null and sr.scenario_id=p_scenario_id and sr.institution_code=public.current_tenant_code()),a as(select coalesce(block_key::text,id::text) activity_key,assignment_id,course_id,teacher_id,class_id,weekday,min(period)::smallint start_p,max(period)::smallint end_p,case when count(distinct classroom_id)<=1 then(array_agg(classroom_id)filter(where classroom_id is not null))[1]else null end classroom_id from raw group by coalesce(block_key::text,id::text),assignment_id,course_id,teacher_id,class_id,weekday)select a.* from a where public.schedule_relation_selector_matches_v1(sel,a.activity_key,a.assignment_id,a.course_id,a.teacher_id,a.class_id);end $$;
create or replace function public.schedule_relation_set_violation_v1(p_relation_id uuid,p_scenario_id uuid default null) returns integer language plpgsql stable security definer set search_path=public as $$ declare t text;p jsonb;m int:=1;n int:=0;cnt int:=0;days int:=0;minp int;maxp int;occupied int:=0;rooms int:=0;begin select upper(relation_type),parameters into t,p from public.schedule_planning_relations where id=p_relation_id and active and tenant_row_allowed(institution_code);if t is null then return 0;end if;m:=coalesce(nullif(coalesce(p->>'max',p->>'value'),'')::int,1);if t='GROUPED' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select distinct weekday,q from a cross join lateral generate_series(start_p,end_p)q) select count(*),count(distinct weekday),min(start_p),max(end_p),(select count(*) from slots) into cnt,days,minp,maxp,occupied from a;if cnt<=1 then return 0;end if;if days<>1 then return greatest(1,cnt-1);end if;return case when maxp-minp+1=occupied then 0 else 1 end;elsif t='MAX_DIFFERENT_ROOMS' then select count(distinct classroom_id) into rooms from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id) where classroom_id is not null;return greatest(0,rooms-m);elsif t='MAX_OCCUPIED_SLOTS' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select distinct weekday,q from a cross join lateral generate_series(start_p,end_p)q where(coalesce(jsonb_array_length(p->'days'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'days')d where d::int=weekday))and(coalesce(jsonb_array_length(p->'periods'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'periods')x where x::int=q)))select count(*) into occupied from slots;return greatest(0,occupied-m);elsif t='MAX_SIMULTANEOUS' then with a as(select * from public.get_schedule_relation_selected_activities_v1(p_relation_id,p_scenario_id)),slots as(select weekday,q,count(*)c from a cross join lateral generate_series(start_p,end_p)q where(coalesce(jsonb_array_length(p->'days'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'days')d where d::int=weekday))and(coalesce(jsonb_array_length(p->'periods'),0)=0 or exists(select 1 from jsonb_array_elements_text(p->'periods')x where x::int=q))group by weekday,q)select coalesce(sum(greatest(c-m,0)),0)::int into n from slots;return n;end if;return 0;end $$;
create or replace function public.get_schedule_generic_relation_evaluation_v2(p_scenario_id uuid default null) returns table(relation_id uuid,relation_type text,mode text,violation_count integer,penalty numeric) language sql stable security definer set search_path=public as $$ select * from public.get_schedule_generic_relation_evaluation_v1(p_scenario_id) where upper(relation_type) not in('PREFERRED_START','GROUPED','MAX_SIMULTANEOUS','MAX_OCCUPIED_SLOTS','MAX_DIFFERENT_ROOMS') union all select r.id,r.relation_type,r.mode,count(*)::int,count(*)*r.weight from public.schedule_planning_relations r join lateral public.get_schedule_relation_selected_activities_v1(r.id,p_scenario_id)a on true where r.active and r.mode<>'OFF' and tenant_row_allowed(r.institution_code) and upper(r.relation_type)='PREFERRED_START' and public.schedule_relation_unary_violates_v1(r.relation_type,r.parameters,a.weekday,a.start_p,a.end_p) group by r.id,r.relation_type,r.mode,r.weight union all select r.id,r.relation_type,r.mode,v.n,v.n*r.weight from public.schedule_planning_relations r cross join lateral(select public.schedule_relation_set_violation_v1(r.id,p_scenario_id)n)v where r.active and r.mode<>'OFF' and tenant_row_allowed(r.institution_code) and upper(r.relation_type) in('GROUPED','MAX_SIMULTANEOUS','MAX_OCCUPIED_SLOTS','MAX_DIFFERENT_ROOMS') and v.n>0 $$;
create or replace function public.get_schedule_scenario_generic_relation_summary_v1(p_scenario_id uuid) returns table(hard numeric,medium numeric,soft numeric,hard_violations integer) language sql stable security definer set search_path=public as $$ select coalesce(sum(penalty)filter(where mode='HARD'),0),coalesce(sum(penalty)filter(where mode='MEDIUM'),0),coalesce(sum(penalty)filter(where mode='SOFT'),0),coalesce(sum(violation_count)filter(where mode='HARD'),0)::int from public.get_schedule_generic_relation_evaluation_v2(p_scenario_id) $$;
create or replace function public.get_schedule_current_generic_relation_summary_v1() returns table(hard numeric,medium numeric,soft numeric,hard_violations integer) language sql stable security definer set search_path=public as $$ select coalesce(sum(penalty)filter(where mode='HARD'),0),coalesce(sum(penalty)filter(where mode='MEDIUM'),0),coalesce(sum(penalty)filter(where mode='SOFT'),0),coalesce(sum(violation_count)filter(where mode='HARD'),0)::int from public.get_schedule_generic_relation_evaluation_v2(null) $$;
create or replace function public.get_schedule_scenario_generic_relation_issues_v1(p_scenario_id uuid) returns table(code text,affected_count integer,detail text) language sql stable security definer set search_path=public as $$ select 'GENERIC_RELATION_'||relation_type,violation_count,'Generic HARD planlama ilişkisi ihlal edildi: '||relation_type from public.get_schedule_generic_relation_evaluation_v2(p_scenario_id) where mode='HARD' and violation_count>0 $$;
